export type RequestBodyTooLargeEnvelope = EnvelopeBase & {
    code?: 2009;
    msg?: 'request_body_too_large';
    data?: {
        /**
         * Which layer of the dual-layer body cap tripped.
         * `envelope` = outer `http.MaxBytesReader` on the
         * whole multipart body (64 KB for
         * `import-auth-json`) or the whole JSON body
         * (96 KiB for `playground/run`);
         * `part` = inner `io.LimitReader` on the
         * `auth_json` part content (16 KB, import only).
         * Callers use this to distinguish preamble-flood
         * attacks (`envelope`) from oversized legitimate
         * payloads (`part`) and log accordingly.
         *
         */
        scope: 'envelope' | 'part';
        /**
         * Byte limit that was crossed. For
         * `import-auth-json`: 65536 when
         * `scope="envelope"` (outer multipart cap);
         * 16384 when `scope="part"` (inner `auth_json`
         * part cap). For `playground/run`: 98304 when
         * `scope="envelope"`. For other single-layer
         * endpoints (setup 8 KiB, settings 16 KiB) the
         * value is the endpoint's configured cap with
         * `scope="envelope"`.
         *
         */
        limit_bytes: number;
    };
};

